import GRDB

struct RecipeRecord: SyncedRecord, Equatable {
    static let syncedTable = SyncedTable.recipes

    var id: String
    var householdId: String
    var name: String
    /// JSON array of `meal_slot` values.
    var mealTypes: String
    /// JSON array of nutrient tags.
    var nutrients: String
    var timeMinutes: Int?
    var servings: Double
    /// JSON array of strings.
    var steps: String
    var notes: String?
    /// Storage path of the cover in `recipe-images`.
    var imagePath: String?
    /// `photo` (taken in the app) or `ai` (generated by an agent through the MCP); `nil` without a cover.
    var imageSource: String?
    var emoji: String?
    var isFavorite: Bool
    var createdAt: String?
    var updatedAt: String?
    var updatedBy: String?
    var deletedAt: String?
    var clientUpdatedAt: String?
    var serverSeq: Int64?
}

struct RecipeIngredientRecord: SyncedRecord, Equatable {
    static let syncedTable = SyncedTable.recipeIngredients

    var id: String
    var householdId: String
    var recipeId: String
    var productId: String
    var quantity: Double?
    var unit: String?
    var position: Int
    var createdAt: String?
    var updatedAt: String?
    var updatedBy: String?
    var deletedAt: String?
    var clientUpdatedAt: String?
    var serverSeq: Int64?
}

struct RecipeComponentRecord: SyncedRecord, Equatable {
    static let syncedTable = SyncedTable.recipeComponents

    var id: String
    var householdId: String
    var parentRecipeId: String
    var childRecipeId: String
    var servingsFactor: Double
    var position: Int
    var createdAt: String?
    var updatedAt: String?
    var updatedBy: String?
    var deletedAt: String?
    var clientUpdatedAt: String?
    var serverSeq: Int64?
}

struct RecipePhotoRecord: SyncedRecord, Equatable {
    static let syncedTable = SyncedTable.recipePhotos

    var id: String
    var householdId: String
    var recipeId: String
    /// `<household>/<recipe>/<uuid>.<ext>` in the `recipe-images` bucket.
    var storagePath: String
    var width: Int?
    var height: Int?
    var position: Int
    var createdAt: String?
    var updatedAt: String?
    var updatedBy: String?
    var deletedAt: String?
    var clientUpdatedAt: String?
    var serverSeq: Int64?
}

struct RecipeLinkRecord: SyncedRecord, Equatable {
    static let syncedTable = SyncedTable.recipeLinks

    var id: String
    var householdId: String
    var recipeId: String
    /// An `http(s)` URL of at most 2048 characters (checked by the server too).
    var url: String
    var position: Int
    var createdAt: String?
    var updatedAt: String?
    var updatedBy: String?
    var deletedAt: String?
    var clientUpdatedAt: String?
    var serverSeq: Int64?
}
